mapper.delete:
delete from ${prefix}WF_TIMER_CONFIG
where proc_def_id = #{procDefId}
      AND proc_inst_id = #{procInstId}
      AND task_def_key = #{taskDefKey}
      AND execution_id = #{executionId}

    AND tc.tenant_id = #{tenantId}

mapper.select:
${limitBefore} select distinct tc.id, tc.proc_def_id procDefId, tc.task_def_key taskDefKey, tc.proc_inst_id procInstId, tc.execution_id executionId, tc.cron_expression cronExpression, tc.time_type timeType, tc.begin_time beginTime, tc.end_time endTime, tc.cfrequency cfrequency, tc.remind_num remindNum, tc.send_type sendType, tc.create_time createTime, tc.note note, tc.status status, tc.template, tc.tenant_id tenantId
,
${field}
${limitBetween}
, row_number() over (ORDER BY RES.ID ) rnk FROM ( select distinct RES.*
${limitAfter}

mapper.sql:
FROM ${prefix}wf_timer_config tc


    AND tc.proc_inst_id = #{processInstanceId}


    AND tc.proc_def_id = #{processDefinitionId}


    AND tc.task_def_key = #{taskDefinitionKey}


    AND tc.tenant_id = #{tenantId}


    AND tc.status = #{status}



 ORDER BY tc.proc_inst_id DESC
